    final hasToken = _present(_reader.getFigmaApiKey());
    final hasOAuth = _present(_reader.getFigmaOAuth2AccessToken());
    if (hasToken || hasOAuth) return const [];
    return const ['FIGMA_TOKEN or FIGMA_OAUTH_ACCESS_TOKEN'];
  }

