// Scratch verification: gh-339 scm_* family visibility in `dmtools list`
// with DEFAULT_SCM set and DMTOOLS_INTEGRATIONS unset (PR #358 behavior).
import 'dart:convert';
import 'dart:io';

import 'package:dmtools/dmtools.dart';
import 'package:test/test.dart';

void main() {
  test('scm_* tools visible in dmtools list when DEFAULT_SCM=github', () async {
    final tmp = Directory.systemTemp.createTempSync('scratch_scm_');
    addTearDown(() {
      PropertyReader.clearOverrides();
      if (tmp.existsSync()) tmp.deleteSync(recursive: true);
    });
    PropertyReader.testIsolation = true;
    PropertyReader.setOverrides({'DEFAULT_SCM': 'github'});
    final lines = <String>[];
    final dispatcher = CliDispatcher(
      writer: lines.add,
      propertyReader: PropertyReader(basePath: tmp.path),
      isTty: () => false,
    );
    expect(await dispatcher.dispatch(['list']), 0);
    final decoded = jsonDecode(lines.join('\n')) as Map<String, dynamic>;
    final names = (decoded['tools'] as List)
        .cast<Map<String, dynamic>>()
        .map((t) => t['name'] as String)
        .toSet();
    // ignore: avoid_print
    print('scm_list_prs visible: ${names.contains('scm_list_prs')}');
    // ignore: avoid_print
    print('github_get_pr visible: ${names.contains('github_get_pr')}');
    // ignore: avoid_print
    print('total tools: ${names.length}');
    expect(names, contains('scm_list_prs'),
        reason: 'gh-339 AC1: DEFAULT_SCM set => family visible in dmtools list');
  });
}

