      _reader.getConfluenceBasePath(),
    );
    if (_reader.getConfluenceLoginPassToken() == null) {
      _addIfAbsent(missing, 'CONFLUENCE_EMAIL', _reader.getConfluenceEmail());
      _addIfAbsent(
        missing,
        'CONFLUENCE_API_TOKEN',
        _reader.getConfluenceApiToken(),
      );
    }
    return missing;
  }

