        : alias.startsWith('source_code_')
            ? defaultSourceCode
            : null;
    if (raw == null) return null;
    final value = raw.trim().toLowerCase();
    return value.isEmpty ? null : value;
  }

  /// Returns the tool definition for [name], resolving aliases.
