      );
      final aliasNames = {...scmAliasToolNames, ...ciAliasToolNames};
      expect(r.registry.allTools.where((t) => aliasNames.contains(t.name)),
          hasLength(aliasNames.length),
          reason: 'each alias must be a distinct new tool');
