    _writer('  version:  $version');
    _writer('  files:    ${result.fileCount}');
    _writer('  zip:      ${result.zipFile.path}');
    _writer('  manifest: ${result.manifestFile.path}');
    _writer('  sha256:   ${result.shaFile.path}');
