void main() {
  test('scm_*/ci_* visible in dmtools list when DEFAULT_SCM/DEFAULT_CI set',
      () async {
    final tmp = Directory.systemTemp.createTempSync('scratch_scm2_');
    addTearDown(() {
      PropertyReader.clearOverrides();
      if (tmp.existsSync()) tmp.deleteSync(recursive: true);
