    final lines = <String>[];
    final dispatcher = CliDispatcher(
      writer: lines.add,
      propertyReader: PropertyReader(basePath: tmp.path),
      isTty: () => false,
    );
    expect(await dispatcher.dispatch(['list']), 0);
    final decoded = jsonDecode(lines.join('\n')) as Map<String, dynamic>;
    final names = (decoded['tools'] as List)
        .cast<Map<String, dynamic>>()
        .map((t) => t['name'] as String)
        .toSet();
    expect(names, contains('scm_list_prs'));
    expect(names, contains('ci_get_merge_state'));
  });

  test('env wins verbatim still hides scm under DMTOOLS_INTEGRATIONS=jira',
      () async {
    final tmp = Directory.systemTemp.createTempSync('scratch_scm3_');
    addTearDown(() {
      PropertyReader.clearOverrides();
      if (tmp.existsSync()) tmp.deleteSync(recursive: true);
    });
    PropertyReader.testIsolation = true;
    PropertyReader.setOverrides({
      'DEFAULT_SCM': 'github',
      'DMTOOLS_INTEGRATIONS': 'jira',
    });
    final lines = <String>[];
    final dispatcher = CliDispatcher(
      writer: lines.add,
      propertyReader: PropertyReader(basePath: tmp.path),
      isTty: () => false,
    );
    expect(await dispatcher.dispatch(['list']), 0);
    final decoded = jsonDecode(lines.join('\n')) as Map<String, dynamic>;
    final integrations = (decoded['tools'] as List)
        .cast<Map<String, dynamic>>()
        .map((t) => t['integration'] as String)
        .toSet();
    expect(integrations, {'jira'});
  });
}
