final RegExp _gitHubKeyHint =
    RegExp(r'^(?:gh-\d+|[\w.-]+/[\w.-]+#\d+)$', caseSensitive: false);

/// Classic Jira key: `PROJ-123`.
final RegExp _jiraKeyHint = RegExp(r'^[A-Z][A-Z0-9]+-\d+$');

/// Bare numeric id — ADO work item.
